namespace SlusserLabs.AnglePlates;

// Holds the generated file headers and the source text of the support types every consumer gets. The support types
// stay as raw strings here, one method per type, so the emitted code reads the same way it lands in the consumer.
internal static class SupportTypes
{
    // No version number, so a package update doesn't change every generated file
    public const string AutoGeneratedHeader = """
        // <auto-generated>
        //     Generated by SlusserLabs.AnglePlates.
        //     Changes to this file will be lost when the project builds.
        // </auto-generated>
        """;

    // The caller escapes the path, because a line break in it would end the comment
    public static string TemplateHeader(string escapedRelativePath) => $"""
        // <auto-generated>
        //     Generated by SlusserLabs.AnglePlates from {escapedRelativePath}.
        //     Changes to this file will be lost when the project builds.
        // </auto-generated>
        """;

    // Generated code opts into nullable annotations whatever the consumer's project sets
    public const string NullableContext = """
        #nullable enable
        """;

    // SupportTypesSnapshotTests is the contract for this string; review its snapshot whenever this changes
    public static string TemplateOptions(string accessModifier) => $$"""
        {{AutoGeneratedHeader}}

        {{NullableContext}}

        namespace SlusserLabs.AnglePlates;

        /// <summary>
        /// Controls how compiled templates encode C# variables. Options can't change after they're created,
        /// so a template and its options are safe to share between threads.
        /// </summary>
        {{accessModifier}} sealed class TemplateOptions
        {
            /// <summary>
            /// Gets options that HTML-encode C# variables with <see cref="global::System.Text.Encodings.Web.HtmlEncoder.Default" />.
            /// Templates use these unless their <c>#encode</c> directive picks another preset.
            /// </summary>
            public static TemplateOptions Html { get; } = new();

            /// <summary>
            /// Gets options that write C# variables as they are, with no encoding.
            /// </summary>
            public static TemplateOptions Unencoded { get; } = new() { Encoder = null };

            /// <summary>
            /// Gets options that encode C# variables for JavaScript strings with <see cref="global::System.Text.Encodings.Web.JavaScriptEncoder.Default" />.
            /// </summary>
            public static TemplateOptions JavaScript { get; } = new() { Encoder = global::System.Text.Encodings.Web.JavaScriptEncoder.Default };

            /// <summary>
            /// Gets options that encode C# variables for URLs with <see cref="global::System.Text.Encodings.Web.UrlEncoder.Default" />.
            /// </summary>
            public static TemplateOptions Url { get; } = new() { Encoder = global::System.Text.Encodings.Web.UrlEncoder.Default };

            /// <summary>
            /// Gets the encoder for C# variables, or <see langword="null" /> to write them unencoded.
            /// The default is <see cref="global::System.Text.Encodings.Web.HtmlEncoder.Default" />.
            /// </summary>
            public global::System.Text.Encodings.Web.TextEncoder? Encoder { get; init; } = global::System.Text.Encodings.Web.HtmlEncoder.Default;

            /// <summary>
            /// Gets the text written in place of a C# variable whose value is <see langword="null" />.
            /// The default writes nothing.
            /// </summary>
            /// <remarks>A visible marker such as <c>"(null)"</c> can help while debugging a template.</remarks>
            public string? NullVariable { get; init; }
        }
        """;

    // SupportTypesSnapshotTests is the contract for this string; review its snapshot whenever this changes
    public static string TextTemplate(string accessModifier) => $$"""
        {{AutoGeneratedHeader}}

        {{NullableContext}}

        namespace SlusserLabs.AnglePlates;

        /// <summary>
        /// The base class of compiled templates that render to a <see cref="global::System.IO.TextWriter" />.
        /// </summary>
        /// <typeparam name="TModel">The type of model the template renders.</typeparam>
        {{accessModifier}} abstract class TextTemplate<TModel>
        {
            /// <summary>
            /// Creates the template with the options it writes C# variables with.
            /// </summary>
            /// <param name="options">The options that control how C# variables are written.</param>
            private protected TextTemplate(TemplateOptions options)
            {
                global::System.ArgumentNullException.ThrowIfNull(options);
                Options = options;
            }

            /// <summary>
            /// Gets the options this template writes C# variables with.
            /// </summary>
            public TemplateOptions Options { get; }

            /// <summary>
            /// Renders the template.
            /// </summary>
            /// <param name="model">The model to render.</param>
            /// <param name="writer">The writer that receives the output. The template doesn't flush or dispose it.</param>
            public abstract void Render(TModel model, global::System.IO.TextWriter writer);

            /// <summary>
            /// Encodes <paramref name="value" /> with the options' encoder and writes it. A <see langword="null" /> value writes
            /// <see cref="TemplateOptions.NullVariable" /> instead.
            /// </summary>
            /// <param name="value">The text to write.</param>
            /// <param name="writer">The writer that receives the output.</param>
            protected void Write(string? value, global::System.IO.TextWriter writer)
            {
                value ??= Options.NullVariable;
                if (string.IsNullOrEmpty(value))
                {
                    return;
                }

                var encoder = Options.Encoder;
                if (encoder is null)
                {
                    writer.Write(value);
                }
                else
                {
                    encoder.Encode(writer, value);
                }
            }

            /// <summary>
            /// Writes <paramref name="value" /> as it is, without encoding. A <see langword="null" /> value writes nothing.
            /// </summary>
            /// <param name="value">The text to write.</param>
            /// <param name="writer">The writer that receives the output.</param>
            protected void WriteRaw(string? value, global::System.IO.TextWriter writer)
            {
                if (!string.IsNullOrEmpty(value))
                {
                    writer.Write(value);
                }
            }

            /// <summary>
            /// Converts <paramref name="value" /> to text with the invariant culture, then encodes and writes it like a string.
            /// </summary>
            /// <param name="value">The value to write.</param>
            /// <param name="writer">The writer that receives the output.</param>
            protected void Write(object? value, global::System.IO.TextWriter writer)
            {
                // Convert.ToString turns null into an empty string, so null is checked first to reach NullVariable
                Write(value is null ? null : global::System.Convert.ToString(value, global::System.Globalization.CultureInfo.InvariantCulture), writer);
            }

            /// <summary>
            /// Formats <paramref name="value" /> with the invariant culture, then encodes and writes it like a string.
            /// </summary>
            /// <typeparam name="T">The type of value, such as a number, date, or enum.</typeparam>
            /// <param name="value">The value to write.</param>
            /// <param name="writer">The writer that receives the output.</param>
            protected void Write<T>(T value, global::System.IO.TextWriter writer)
                where T : global::System.IFormattable?
            {
                Write(value is null ? null : value.ToString(null, global::System.Globalization.CultureInfo.InvariantCulture), writer);
            }

            /// <summary>
            /// Formats <paramref name="value" /> with the invariant culture, then encodes and writes it like a string.
            /// </summary>
            /// <typeparam name="T">The type of value, such as a number, date, or enum.</typeparam>
            /// <param name="value">The value to write.</param>
            /// <param name="writer">The writer that receives the output.</param>
            protected void Write<T>(T? value, global::System.IO.TextWriter writer)
                where T : struct, global::System.IFormattable
            {
                Write(value.HasValue ? value.GetValueOrDefault().ToString(null, global::System.Globalization.CultureInfo.InvariantCulture) : null, writer);
            }

            /// <summary>
            /// Writes literal template text.
            /// </summary>
            /// <param name="value">The text to write.</param>
            /// <param name="writer">The writer that receives the output.</param>
            private protected static void WriteLiteral(string value, global::System.IO.TextWriter writer)
            {
                writer.Write(value);
            }
        }
        """;

